<form class="card-block stack" method="post" action="<?= e(url('/admin/customers/' . $customer['id'])) ?>"><?= csrf_field() ?><label><?= e(__('fields.name')) ?><input name="name" value="<?= e($customer['name']) ?>"></label><label><?= e(__('fields.phone')) ?><input name="phone" value="<?= e((string) $customer['phone']) ?>"></label><label><?= e(__('fields.whatsapp')) ?><input name="whatsapp" value="<?= e((string) $customer['whatsapp']) ?>"></label><label><?= e(__('fields.address')) ?><input name="address" value="<?= e((string) $customer['address']) ?>"></label><label><?= e(__('fields.notes')) ?><textarea name="notes"><?= e((string) $customer['notes']) ?></textarea></label><label class="consent"><input type="checkbox" name="is_active" value="1" <?= (int) $customer['is_active'] === 1 ? 'checked' : '' ?>> <?= e(__('admin.active')) ?></label><button class="btn btn-primary" type="submit"><?= e(__('actions.save')) ?></button></form>
<section class="card-block"><h2><?= e(__('admin.cases')) ?></h2><?php foreach ($cases as $case): ?><p><a href="<?= e(url('/admin/cases/' . $case['id'])) ?>"><?= e($case['number']) ?></a> <?= e($case['status_name']) ?></p><?php endforeach; ?></section>
<section class="card-block"><h2><?= e(__('admin.quotations')) ?></h2><?php foreach ($quotations as $row): ?><p><?= e($row['number']) ?> <?= e($row['status']) ?></p><?php endforeach; ?></section>
<section class="card-block"><h2><?= e(__('admin.invoices')) ?></h2><?php foreach ($invoices as $row): ?><p><?= e($row['number']) ?> <?= e($row['status']) ?></p><?php endforeach; ?></section>
